import re

_WORD_RE = re.compile(r"[A-Za-z][A-Za-z']*")
_STOP = frozenset(("this", "the", "a", "an", "of", "in", "on", "for", "with",
                   "as", "by", "and", "or", "to", "before", "after", "that",
                   "is", "was", "are", "were", "be", "made", "his", "her",
                   "its", "their", "he", "she", "it", "they", "from", "at"))
_THIS_RE = re.compile(r"\bthis\b\s+[A-Za-z]")
_PHRASE_RE = re.compile(r"\b([A-Z][A-Za-z']*(?:\s+[A-Z][A-Za-z']*){0,3})\b")


def applies(view):
    q = view.get("question", "")
    return bool(_THIS_RE.search(q))


def _content_words(text):
    return [w.lower() for w in _WORD_RE.findall(text)
            if w.lower() not in _STOP and len(w) > 2]


def before_call(view, state):
    q = view.get("question", "")
    ctx = view.get("context", "")
    qwords = _content_words(q)
    if not qwords:
        return None
    needed = max(1, (len(qwords) + 1) // 2)
    sentences = re.split(r"(?<=[.!?])\s+|\.\.\.", ctx)
    matches = []
    for s in sentences:
        words = set(_content_words(s))
        hit = sum(1 for w in qwords if w in words)
        if hit >= needed:
            matches.append(s)
    if not matches:
        return None
    qlower = q.lower()
    cands = []
    seen = set()
    for s in matches:
        for m in _PHRASE_RE.finditer(s):
            phr = m.group(0).strip()
            if phr.lower() in qlower:
                continue
            key = phr.lower()
            if key in seen:
                continue
            seen.add(key)
            if len(phr) <= 120:
                cands.append(phr)
            if len(cands) >= 8:
                break
        if len(cands) >= 8:
            break
    if not cands:
        return None
    facts = ["Question content words matched by at least half: %d matching snippet sentences." % len(matches)]
    return {"facts": facts, "candidates": cands}
